cat > $P/Alias.java <<'EOF'
package net.officefloor.hq.app.person;

/** The alias just given to a person, for the audit line. */
public record Alias(String alias) {
}
EOF
cat > $P/ValidateAlias.java <<'EOF'
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Binds the alias asked for, trimmed: refused when it is blank. */
public class ValidateAlias {
    public void validate(@RequestBody AliasRequest request, Out<AliasRequest> body)
            throws InvalidPersonException {
        String alias = request == null || request.alias() == null ? "" : request.alias().trim();
        if (alias.isEmpty()) {
            throw new InvalidPersonException("An alias is required");
        }
        body.set(new AliasRequest(alias));
    }
}
EOF
cat > $P/AddAlias.java <<'EOF'
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Gives the person the alias: refused (nothing written) when it equals, as names are compared,
 *  any name or alias on the sheet. */
public class AddAlias {
    public void add(@RequestParam(name = "by", required = false) String by,
            @Val AliasRequest request, @Val Person person, PersonRepository people,
            Out<Alias> added) throws InvalidPersonException {
        if (people.nameTaken(person.getSheetId(), request.alias(), null)) {
            throw new InvalidPersonException("The alias is already in use");
        }
        people.addAlias(person, request.alias(), by == null ? "" : by);
        added.set(new Alias(request.alias()));
    }
}
EOF
cat > $P/RecordAliasAdded.java <<'EOF'
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the alias just given (PERSON_ALIAS_ADDED). */
public class RecordAliasAdded {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Person person, @Val Alias alias, Audit audit) {
        audit.record("PERSON_ALIAS_ADDED sheet=" + person.getSheetId() + " by=" + (by == null ? "" : by)
                + " name=" + person.getName() + " alias=" + alias.alias());
    }
}
EOF

