            @Val Person person, @Val Alias alias, Audit audit) {
        audit.record("PERSON_ALIAS_ADDED sheet=" + person.getSheetId() + " by=" + (by == null ? "" : by)
                + " name=" + person.getName() + " alias=" + alias.alias());
    }
}
